import { useRef, useEffect } from 'react';

export default function Modal({ open, onClose, triggerRef, ariaLabelledby, children }) {
  const dialogRef = useRef(null);

  useEffect(() => {
    const dialog = dialogRef.current;
    if (open) {
      dialog.showModal();
      // Focus the first focusable element automatically? dialog handles it, but we can also set initial focus.
    } else {
      dialog.close();
    }
  }, [open]);

  useEffect(() => {
    const dialog = dialogRef.current;
    const handleClose = () => {
      onClose?.();
      triggerRef?.current?.focus();
    };
    dialog.addEventListener('close', handleClose);
    return () => dialog.removeEventListener('close', handleClose);
  }, [onClose, triggerRef]);

  return (
    <dialog ref={dialogRef} aria-labelledby={ariaLabelledby} aria-modal="true">
      {children}
    </dialog>
  );
}
